// Filter and clean data
const stocks = rawData.filter(d => d.ticker && d.sector).map(d => {
    const cap = d.marketCap !== null && d.marketCap !== undefined ? parseFloat(d.marketCap) : null;
    // Classify ETF using source sector name if available, otherwise fallback to missing cap
    const isETF = (d.sector && d.sector.toUpperCase() === 'ETF') || (cap === null);
    return {
        ticker: d.ticker,
        name: d['full name'] || d.name || d.ticker,
        sector: d.sector,
        marketCap: cap,
        isETF: isETF
    };
});

